/**
 * Single upcast converter to the <card/> element with all its attributes.
 */

const upcastCardChild = (writer, convertChildren, viewElement, modelElement, matcher, tagName) => {
	const el = findDescendant(viewElement, (c) => c.name && matcher(c));
	
	const child = writer.createElement(tagName);
	writer.insert(child, modelElement, 'end');

	if (el) {
		convertChildren(el, child);
	}

	return child;
}

const upcastCard = (viewElement, { writer, convertChildren }) => {
	const card = writer.createElement('card');

	const type = viewElement.getAttribute('type') || 'section';
	writer.setAttribute('type', type, card);

	const expandable = viewElement.getAttribute('expandable') || viewElement.hasClass('details-box');
	writer.setAttribute('expandale', expandable ? true : null, card);

	const important = viewElement.getAttribute('important')
	writer.setAttribute('important', important ? true : null, card);

	upcastCardChild(writer, convertChildren, viewElement, card, (c) => c.hasClass('card-title') || c.hasClass('details-box-caption'), 'cardTitle');
	const cardContent = upcastCardChild(writer, convertChildren, viewElement, card, (c) => c.hasClass('card-content') || c.hasClass('details-box-content'), 'cardContent');
	const cardUrl = upcastCardChild(writer, convertChildren, viewElement, card, (c) => c.hasClass('card-url'), 'cardUrl');
	upcastCardChild(writer, convertChildren, viewElement, card, (c) => c.hasClass('card-cta'), 'cardCta');


	const oembed = findDescendant(viewElement, (c) => c.name == 'oembed');
	if (oembed) {
		const url = oembed.getAttribute( 'url' ) || oembed.getAttribute( 'data-oembed-url' );
		writer.insertText(url, cardUrl, 0);
	}

	if (!cardContent.getChild(0)) {
		const paragraph = writer.createElement('paragraph')
		writer.insertText('', paragraph, 0);
		writer.insert(paragraph, cardContent, 'end');
	}

	return card;
};

const validParent = (context, childDefinition) => {
	if (context.startsWith('card') && childDefinition.name == 'card') {
		return false;
	}
}

/**
 * Helper for creating a DOM button with an editor callback.
 */
const addActionButton = (text, callback, domElement, editor) => {
	const domDocument = domElement.ownerDocument;

	const button = createElement(domDocument, 'button', {}, [text]);

	button.addEventListener('click', (e) => {
		editor.model.change(callback);
		e.preventDefault();
	});

	domElement.appendChild(button);

	return button;
};
function findDescendant(modelElement, predicate) {
	if (modelElement.getChildren) {
		for (let child of modelElement.getChildren()) {
			if (predicate(child)) {
				return child
			} 
			const found = findDescendant(child, predicate)
			if (found) {
				return found
			}
		}
	}
}
/**
 * Helper function that creates the card editing UI inside the card.
 */
const createActionsView = (editor, modelElement) => function (domElement) {



	const input = createElement(domElement.ownerDocument, 'input', { type: 'file' });
	input.onchange = (e) => {
		editor.model.change(writer => {
			const image = findDescendant(modelElement, (e) => e.name == 'imageBlock');
			if (image) {
				writer.setSelection(image, 'on');
			} else {
				const content = findDescendant(modelElement, (e) => e.name == 'cardContent');
				const paragraph = writer.createElement('paragraph');
				writer.insert(paragraph, content, 0);
				writer.setSelection(paragraph, 0);
			}
			editor.editing.view.focus();
		});
		editor.execute('imageUpload', { file: input.files[0] })
		setTimeout(() => {
			input.value = '';
		}, 50)
		e.preventDefault();
	};
	
	const label = createElement(domElement.ownerDocument, 'label', { class: 'upload-image'});
	label.textContent = 'Upload image';
	label.appendChild(input)
	domElement.appendChild(label);
	
	const checkbox = createElement(domElement.ownerDocument, 'input', {type: 'checkbox', checked: modelElement.getAttribute('expandale')});
	const checkboxLabel = createElement(domElement.ownerDocument, 'label', { class: 'make-expandable'}, [
		checkbox,
		createElement(domElement.ownerDocument, 'span')
	]);
	checkbox.checked = modelElement.getAttribute('expandale');
	domElement.appendChild(checkboxLabel);
	checkbox.onclick = (e) => {
		editor.model.enqueueChange('transparent', writer => {
			writer.setAttribute('expandale', modelElement.getAttribute('expandale') ? null : true, modelElement);
		});
	}


	const checkbox2 = createElement(domElement.ownerDocument, 'input', {type: 'checkbox', checked: modelElement.getAttribute('important')});
	const checkbox2Label = createElement(domElement.ownerDocument, 'label', { class: 'make-important'}, [
		checkbox2,
		createElement(domElement.ownerDocument, 'span')
	]);
	checkbox2.checked = modelElement.getAttribute('important');
	domElement.appendChild(checkbox2Label);
	checkbox2.onclick = (e) => {
		editor.model.enqueueChange('transparent', writer => {
			writer.setAttribute('important', modelElement.getAttribute('important') ? null : true, modelElement);
		});
	}


	const currentType = modelElement.getAttribute('type');

	//
	// Change the card action button.
	//
	const types = ['section', 'card', 'example', 'definition', 'media', 'materials', 'eureka', 'promo', 'lesson', 'lock', 'question'];

	const select = createElement(domElement.ownerDocument, 'select', {
		class: 'card-tabs',
	}, types.map((type) => {
		const option = createElement(domElement.ownerDocument, 'option', {
			class: 'card-tab-' + type,
			value: type,
		}, [type]);
		return option;
	}));
	select.value = currentType;
	select.oninput = (e) => {
		editor.model.change(writer => {
			writer.setAttribute('type', e.target.value, modelElement);
		});
	}

	domElement.appendChild(select);

};

/**
 * The downcast converter for the <card/> element.
 *
 * It returns the full view structure based on the current state of the model element.
 */
const fetchCardData = (editor, modelElement, embed) => {
	const cardUrl = findDescendant(modelElement, (e) => e.name == 'cardUrl');
	if (!cardUrl.getChild(0)) return;
	const url = cardUrl.getChild(0).data.trim();
	if (!url) return;
	const endpoint = '/embeds?url=' + encodeURIComponent(url);
	
	editor.model.enqueueChange('transparent', writer => {
		writer.setAttribute('request', 'loading', modelElement)
	})
	fetchFromAPIWithResponse(endpoint, {
		method: 'put'
	}).then(({ data }) => {
		setCardData(editor, modelElement, data);
	}).finally(() => {
		editor.model.enqueueChange('transparent', writer => {
			writer.setAttribute('request', null, modelElement)
		})
	})
}
const setCardData = (editor, modelElement, embed) => {
	editor.model.change(writer => {
		const oldImageBlock = findDescendant(modelElement, (e) => e.name == 'imageBlock');
		const cardContent = findDescendant(modelElement, (e) => e.name == 'cardContent');
		const oldDescription = Array.from(cardContent.getChildren()).filter((c) => c.name != 'imageBlock');

		if (embed.title) {
			const cardTitle = findDescendant(modelElement, (e) => e.name == 'cardTitle');
			writer.remove(writer.createRangeIn(cardTitle));
			writer.insertText(embed.title, cardTitle, 0);
		}
		
		writer.remove(writer.createRangeIn(cardContent));
		if (embed.image) {
			const newImage = writer.createElement('imageBlock', {
				src: embed.image
			} );
			
		  writer.insert(newImage, cardContent, 0);
		}

		const paragraph = writer.createElement('paragraph')
		writer.insertText(embed.description, paragraph, 0);
		writer.insert(paragraph, cardContent, 'end');

	});
}

const createViewElement = ({ writer, view, consumable, asWidget, mapper, cardView }, tag, className, placeholder, child, attributes) => {
	var elementView = writer.createEditableElement(tag, { class: className });

	if (placeholder) enablePlaceholder({
		view,
		element: elementView,
		text: placeholder,
		keepOnFocus: true
	});

	consumable.consume(child, 'insert');
	mapper.bindElements(child, elementView);

	if (asWidget) {
		toWidgetEditable(elementView, writer);
	}

	const target = child && (child.name == 'cardContent' ? child.getChild(0) : child);
	if (asWidget || target && findDescendant(child, c => (!c.isEmpty || c.name == 'imageBlock'))) {
		if (child.name == 'cardContent') {
			if (findDescendant(child, (c) => c.name == 'imageBlock'))
				writer.addClass('with-image', cardView);
			if (findDescendant(child, (c) => c.name != 'imageBlock' && !c.isEmpty))
				writer.addClass('with-text', cardView);
		}
		writer.addClass(className.split(' ').pop().replace('card', 'with'), cardView);
		writer.insert(writer.createPositionAt(cardView, 'end'), elementView);
	}
	return elementView;
} 


