function writeCard(writer, { url, content, title, type = 'section', expandable = false, important = false, request = 'initial'} = {}) {
	const card = writer.createElement('card', { type, expandable, important, request  });
	const cardTitle = writer.createElement('cardTitle');
	const cta = writer.createElement('cardCta');
	const cardUrl = writer.createElement('cardUrl');
	const cardContent = writer.createElement('cardContent');
	const paragraph1 = writer.createElement('paragraph');

	writer.insert(cardTitle, card, 0);
	if (title)
		writer.insertText(title, cardTitle, 0);

	writer.insert(cardContent, card, 1);
	if (content)
		writer.insert(content, cardContent, 0);
	else
		writer.insert(paragraph1, cardContent, 0);
	writer.insert(cta, card, 2);
	writer.insert(cardUrl, card, 3);
	if (cardUrl)
		writer.insertText(url, cardUrl, 0);

	return card;
}

class InsertCardCommand extends Command {
	/**
	 * Refresh used schema definition to check if a side card can be inserted in the current selection.
	 */
	refresh() {
		const model = this.editor.model; 
		const range = findOptimalInsertionRange(model.document.selection, model);
		
		this.isEnabled = true;
		
		for (var p = model.document.selection.focus.parent; p = p.parent;) {
			if (p.name == 'card')
				this.isEnabled = false;
		}
		//this.isEnabled = true; 
	}

	/**
	 * Creates a full side card element with all required children and attributes.
	 */
	execute(options = {}) {
		const model = this.editor.model;


		model.change(writer => {
			options.content = writer.createDocumentFragment();
	
			const blocks = Array.from(model.document.selection.getSelectedBlocks()).filter((block) => {
				if (block.name == 'card') return false;
				writer.remove(block)
				console.error(block.name)
				if (block.name == 'heading2' || block.name == 'heading3' || block.name == 'heading1') {
					options.title = block.getChild(0).data;
					return false;
				} else {
					writer.append(writer.cloneElement(block), options.content);
					return true;
				}
			});

			
			model.enqueueChange((writer) => {
				const insertionRange = findOptimalInsertionRange(model.document.selection, model);
				insertionRange.start = insertionRange.end;


				const card = writeCard(writer, options);
				const title = findDescendant(card, c => c.name == 'cardTitle');

				model.insertContent(card, insertionRange);
				writer.setSelection(writer.createPositionAt(title, 0));
			})
		});
	}
}

class Card extends Plugin {
	constructor(editor) {
		super(editor);

		this._defineSchema();
		this._defineConversion();



		editor.commands.add('insertCard', new InsertCardCommand(editor));

		this._defineUI();
	}

	_defineConversion() {
		const editor = this.editor;
		const conversion = editor.conversion;

/*		editor.editing.downcastDispatcher.on( 'attribute:request', ( evt, data, conversionApi ) => {
			if (data.attributeNewValue != 'pending') return;

			if (!conversionApi.consumable.consume(data.item, evt.name)) {
					return;
			}
			if (!this.editor.config) {
					return;
			}

			if (data.attributeNewValue) {
				fetchCardData(editor, data.item.parent);
			}

			return;
		} ); */

		conversion.for( 'upcast' )
			// Upcast semantic media.
			.elementToElement( {
				view: {
					name: 'figure',
					classes: ['media']
				},
				model: ( viewMediaFigure, { writer } ) => {
					// This would have to be smarter:
					const oembed = viewMediaFigure.getChild( 0 );
					const url = oembed.getAttribute( 'url' ) || oembed.getAttribute( 'data-oembed-url' );

					return writeCard(writer, { url, request: 'pending', type: 'media'});
				},
				// Execute it before the standard converter.
				converterPriority: 'high'
			} );



			conversion.for('upcast')
			.elementToElement({
				view: { name: 'figure', classes: ['details-box'] },
				model: upcastCard
			})


		conversion.for('upcast')
			.elementToElement({
				view: { name: 'figure', classes: ['card'] },
				model: upcastCard
			})

		// The downcast conversion must be split as you need a widget in the editing pipeline.
		conversion.for('editingDowncast').elementToElement({
			model: 'card',
			view: downcastSideCard(editor, { asWidget: true }),
			triggerBy: {
				attributes: ['request'],
			}
		});
		// The data downcast is always executed from the current model stat, so `triggerBy` will take no effect.
		conversion.for('dataDowncast').elementToElement({
			model: 'card',
			view: downcastSideCard(editor, { asWidget: false })
		});
	}

	_defineSchema() {
		const schema = this.editor.model.schema;

		// The main element with attributes for type and Url:
		schema.register('card', {
			allowWhere: '$block',
			allowIn: '$root',
			isObject: true,
			allowAttributes: ['type', 'expandale', 'important', 'request']
		});
		// Disallow side card nesting.
		schema.addChildCheck((context, childDefinition) => {
 			if (![...context.getNames()].includes('card')) {

				if (([...context.getNames()].includes('figure')
				|| [...context.getNames()].includes('imageBlock')) && childDefinition.name === 'card') {
					return false;
				}
				return;
			};

			if (childDefinition.name === 'card') {
				return false;
			}
			if ([...context.getNames()].includes('paragraph') && childDefinition.name === 'imageBlock') {
				return false;
			}
			if ([...context.getNames()].includes('cardContent') && childDefinition.name === 'imageBlock') {
				return true;
			}
			if ([...context.getNames()].includes('cardContent') && childDefinition.name === 'imageInline') {
				return false;
			}
		});

		schema.register('cardTitle', {
			isLimit: true,
			allowIn: 'card'
		});
		schema.extend('$text', { allowIn: 'cardTitle' });
		
		/*schema.addAttributeCheck(context => {
			if (context.endsWith('cardTitle $text')) {
				return false;
			}
		});*/


		schema.register('cardContent', {
			//isLimit: true,
			isSelectable: true,
			allowIn: 'card',
			allowContentOf: '$root'
		});


		// A text-only title.
		schema.register('cardCta', {
			isLimit: true,
			allowIn: 'card'
		});
		schema.extend('$text', { allowIn: 'cardCta' });


		schema.register('cardUrl', {
			isLimit: true,
			allowIn: 'card',
		});
		schema.extend('$text', { allowIn: 'cardUrl' });

		schema.addAttributeCheck(context => {
			if (context.endsWith('cardUrl $text')) {
				return false;
			}
		});
	}

	_defineUI() {
		const editor = this.editor;

		// Defines a simple text button.
		editor.ui.componentFactory.add('insertCard', locale => {
			const button = new ButtonView(locale);

			const command = editor.commands.get('insertCard');

			button.set({
				withText: true,
				icon: false,
				label: 'Figure (cmd+d)' 
			});

			button.bind('isEnabled').to(command);

			button.on('execute', () => {
				editor.execute('insertCard');
				editor.editing.view.focus();
			});

			return button;
		});
	}
}

export default Card;





const URL_REGEXP = /^(?:http(s)?:\/\/)?[\w-]+\.[\w-.~:/?#[\]@!$&'()*+,;=%]+$/;

class AutoCardEmbed extends Plugin {
	/**
	 * @inheritDoc
	 */
	static get requires() {
		return [ Clipboard, Undo ];
	}

	/**
	 * @inheritDoc
	 */
	static get pluginName() {
		return 'AutoMediaEmbed';
	}

	/**
	 * @inheritDoc
	 */
	constructor( editor ) {
		super( editor );

		/**
		 * The paste–to–embed `setTimeout` ID. Stored as a property to allow
		 * cleaning of the timeout.
		 *
		 * @private
		 * @member {Number} #_timeoutId
		 */
		this._timeoutId = null;

		/**
		 * The position where the `<media>` element will be inserted after the timeout,
		 * determined each time the new content is pasted into the document.
		 *
		 * @private
		 * @member {module:engine/model/liveposition~LivePosition} #_positionToInsert
		 */
		this._positionToInsert = null;
	}

	/**
	 * @inheritDoc
	 */
	init() {
		const editor = this.editor;
		const modelDocument = editor.model.document;

		// We need to listen on `Clipboard#inputTransformation` because we need to save positions of selection.
		// After pasting, the content between those positions will be checked for a URL that could be transformed
		// into media.
		this.listenTo( editor.plugins.get( 'ClipboardPipeline' ), 'inputTransformation', () => {
			const firstRange = modelDocument.selection.getFirstRange();

			const leftLivePosition = LivePosition.fromPosition( firstRange.start );
			leftLivePosition.stickiness = 'toPrevious';

			const rightLivePosition = LivePosition.fromPosition( firstRange.end );
			rightLivePosition.stickiness = 'toNext';

			modelDocument.once( 'change:data', () => {
				this._embedMediaBetweenPositions( leftLivePosition, rightLivePosition );

				leftLivePosition.detach();
				rightLivePosition.detach();
			}, { priority: 'high' } );
		} );

		editor.commands.get( 'undo' ).on( 'execute', () => {
			if ( this._timeoutId ) {
				global.window.clearTimeout( this._timeoutId );
				this._positionToInsert.detach();

				this._timeoutId = null;
				this._positionToInsert = null;
			}
		}, { priority: 'high' } );
	}

	/**
	 * Analyzes the part of the document between provided positions in search for a URL representing media.
	 * When the URL is found, it is automatically converted into media.
	 *
	 * @protected
	 * @param {module:engine/model/liveposition~LivePosition} leftPosition Left position of the selection.
	 * @param {module:engine/model/liveposition~LivePosition} rightPosition Right position of the selection.
	 */
	_embedMediaBetweenPositions( leftPosition, rightPosition ) {
		const editor = this.editor;
		// TODO: Use marker instead of LiveRange & LivePositions.
		const urlRange = new LiveRange( leftPosition, rightPosition );
		const walker = urlRange.getWalker( { ignoreElementEnd: true } );

		let url = '';

		for ( const node of walker ) {
			if ( node.item.is( '$textProxy' ) ) {
				url += node.item.data;
			}
		}

		url = url.trim();

		// If the URL does not match to universal URL regexp, let's skip that.
		if ( !url.match( URL_REGEXP ) ) {
			urlRange.detach();

			return;
		}

		const mediaEmbedCommand = editor.commands.get( 'insertCard' );

		// Do not anything if media element cannot be inserted at the current position (#47).
		if ( !mediaEmbedCommand.isEnabled ) {
			urlRange.detach();

			return;
		}

		// Position won't be available in the `setTimeout` function so let's clone it.
		this._positionToInsert = LivePosition.fromPosition( leftPosition );

		// This action mustn't be executed if undo was called between pasting and auto-embedding.
		this._timeoutId = global.window.setTimeout( () => {
			editor.model.change( writer => {
				this._timeoutId = null;

				writer.remove( urlRange );
				urlRange.detach();

				let insertionPosition;

				// Check if position where the media element should be inserted is still valid.
				// Otherwise leave it as undefined to use document.selection - default behavior of model.insertContent().
				if ( this._positionToInsert.root.rootName !== '$graveyard' ) {
					insertionPosition = this._positionToInsert;
				}

				editor.execute('insertCard', { url, request: 'pending', type: url.includes('youtu') ? 'media' : 'card' })

				this._positionToInsert.detach();
				this._positionToInsert = null;
			} );
		}, 100 );
	}
}

Card.AutoCardEmbed = AutoCardEmbed;