import Plugin from '@ckeditor/ckeditor5-core/src/plugin';

import ButtonView from '@ckeditor/ckeditor5-ui/src/button/buttonview';

import { toWidget, toWidgetEditable } from '@ckeditor/ckeditor5-widget/src/utils';

class InsertQuestion extends Plugin {
	init() {
		const editor = this.editor;

		this._defineSchema();
		this._defineConverters();

		editor.ui.componentFactory.add( 'insertQuestion', locale => {
			const view = new ButtonView( locale );

			view.set( {
				label: 'Insert question',
				icon: '<svg xmlns="http://www.w3.org/2000/svg" height="24" viewBox="0 0 24 24" width="24"><path d="M0 0h24v24H0z" fill="none"/><path d="M11 18h2v-2h-2v2zm1-16C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm0 18c-4.41 0-8-3.59-8-8s3.59-8 8-8 8 3.59 8 8-3.59 8-8 8zm0-14c-2.21 0-4 1.79-4 4h2c0-1.1.9-2 2-2s2 .9 2 2c0 2-3 1.75-3 5h2c0-2.25 3-2.5 3-5 0-2.21-1.79-4-4-4z"/></svg>',
				tooltip: true
			} );

			// Callback executed once the image is clicked.
			view.on( 'execute', () => {
				editor.model.change( writer => {
					const question = writer.createElement( 'question' );

					// Insert the image in the current selection location.
					editor.model.insertContent( question, editor.model.document.selection );
				} );
			} );

			return view;
		} );
	}

	_defineSchema() {
		const schema = this.editor.model.schema;

		schema.register( 'question', {
			// Behaves like a self-contained object (e.g. an image).
			isObject: true,

			allowAttributes: [ 'number' ],

			// Allow in places where other blocks are allowed (e.g. directly in the root).
			allowWhere: '$block'
		} );
	}

	_defineConverters() {
		const conversion = this.editor.conversion;

		// <detailsBox> converters
		conversion.for( 'upcast' ).elementToElement( {
			model: ( viewElement, {writer} ) => {
				return writer.createElement( 'question', { number: viewElement.getAttribute( 'data-number' ) } );
			},
			view: {
				name: 'section',
				classes: 'question'
			}
		} );
		conversion.for( 'dataDowncast' ).elementToElement( {
			model: 'question',
			view: ( modelElement, {writer} ) => {
				let index = 0;
				for ( let p = modelElement; p = p.previousSibling; ) {
					if ( p.name === 'question' )
					{ index++; }
				}
				const number = { 'data-number': index };
				return writer.createContainerElement( 'section', { class: 'question', ...number } );
			}
		} );
		conversion.for( 'editingDowncast' ).elementToElement( {
			model: 'question',
			view: ( modelElement, {writer} ) => {
				let index = 0;
				for ( let p = modelElement; p = p.previousSibling; ) {
					if ( p.name === 'question' )
					{ index++; }
				}
				const number = { 'data-number': index };
				const section = writer.createContainerElement( 'section', { class: 'question', ...number } );

				return toWidget( section, writer, { label: 'Question' } );
			}
		} );
	}
}

export default InsertQuestion;
